const snippets={"Python": ["from typing import List, Optional", "from collections import deque", "", "class Solution:", "", "    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:", "        ans = []", "        if root is None:", "            return ans", "        q = deque([root])", "        while q:", "            ans.append(q[0].val)", "            for _ in range(len(q)):", "                node = q.popleft()", "                if node.right:", "                    q.append(node.right)", "                if node.left:", "                    q.append(node.left)", "        return ans"], "Java": ["import java.util.*;", "class Solution {", "    public List<Integer> rightSideView(TreeNode root) {", "        List<Integer> ans = new ArrayList<>();", "        if (root == null) {", "            return ans;", "        }", "        Deque<TreeNode> q = new ArrayDeque<>();", "        q.offer(root);", "        while (!q.isEmpty()) {", "            ans.add(q.peekFirst().val);", "            for (int k = q.size(); k > 0; --k) {", "                TreeNode node = q.poll();", "                if (node.right != null) {", "                    q.offer(node.right);", "                }", "                if (node.left != null) {", "                    q.offer(node.left);", "                }", "            }", "        }", "        return ans;", "    }", "}"]};
